import sys
sys.path.insert(0, "<project>/research/10_frontier/G1_zeta3_any_angle")
import mpmath as mp
import corner_series as csmod
mp.mp.dps = 100
Ms = csmod.corner_coeffs(2*mp.pi/3, 3)
stored = {
 0: "-0.",
 1: "0.",
 2: "-0.",
 3: "0.",
}
for k in range(4):
    st = mp.mpf(stored[k])
    print(f"M{k}: got {mp.nstr(Ms[k], 12)}  stored {mp.nstr(st, 12)}  |err| {mp.nstr(abs(Ms[k]-st),2)}")
